import attr


@attr.s(cmp=False)
class Cbam(object):
    """

    :param str addr: IP ADDRESS or FQDN
    :param str client_id: login parameter to cbam
    :param str client_secret: password parameter to cbam
    """
    addr = attr.ib(type=str)
    client_id = attr.ib(type=str)
    client_secret = attr.ib(type=str)
